// 真实Common分配/cache/history/裁剪；业务源是typed夹具，未代原Task钱物和Known授权运行。
#include "resident/domains/tasks/personal_cancellations/task_personal_cancellation_receipts.hpp"
#include "resident/kernel/command_types.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void need(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
struct Fixture {
 std::shared_ptr<CommonCatalog> catalog=std::make_shared<CommonCatalog>();CommonStore common{CommonState{},catalog};TaskPersonalCancellationState state;
 Fixture(){common.state().identity.execution_epoch=1;common.state().metadata.player_actor_id="carrier";ActorRecord actor;actor.id="carrier";actor.alive=true;actor.available=true;common.state().actors.insert(actor.id,actor);}
 StableId cancel(){auto id=common.next_id(task_personal_cancelled_kind);need(id.ok&&common.append_fact({id.value,task_personal_cancelled_kind,task_personal_cancellation_module}).ok,"actual Common cancellation fact");TaskPersonalCancellationRecord r;r.fact_id=id.value;r.carrier_actor_id="carrier";r.tick=common.tick();state.cancellations.insert(id.value,r);return id.value;}
 std::shared_ptr<CommitResult> commit(const StableId& source,Integer request){auto id=common.next_id("result");need(id.ok,"actual result allocation");auto r=std::make_shared<CommitResult>();r->kind=task_personal_cancellation_command;r->result_id=id.value;r->tick=common.tick();r->revision=++common.state().identity.revision;InteractionEffect effect;effect.settlement_result=source;r->details=std::make_shared<ReceiptDetails>(ReceiptDetails{effect,{}});common.state().request_sequences.set("carrier",request);common.state().results.set("carrier:"+std::to_string(request),r);common.state().history.push_back({r->tick,r->kind,"carrier",r->result_id,{}});return r;}
};}
int main(){try{Fixture f;const auto before=f.state;const auto id=f.cancel();auto r=f.commit(id,1);auto added=task_personal_cancellation_new_result_source(before,f.state,"carrier",r->kind,*r->details,0);need(added.ok&&added.value==id,"exactly one real newly cancelled source");need(!validate_task_personal_cancellation_results(f.common,&f.state).ok,"unbound source is never stable bank");auto copied=*r;need(!bind_task_personal_cancellation_result(f.common,f.state,id,"carrier",1,copied).ok,"copied result is not actual Common object");need(bind_task_personal_cancellation_result(f.common,f.state,id,"carrier",1,*r).ok,"actual cache/history object binds");need(validate_task_personal_cancellation_results(f.common,&f.state).ok,"stable bound receipt validates");auto original=f.state;f.common.state().results={};f.common.state().history.clear();need(validate_task_personal_cancellation_results(f.common,&f.state).ok,"permanent result survives full pruning");f.state.cancellations.find(id)->actual_result.reset();need(!validate_task_personal_cancellation_results(f.common,&f.state).ok,"full pruning cannot remove mandatory permanent binding");f.state=original;
 auto other=f.common.next_id("other");need(other.ok&&f.common.append_fact({other.value,"other","fixture"}).ok,"actual unrelated fact exists");f.state.cancellations.find(id)->actual_result->result_id="result:"+other.value.substr(other.value.find(':')+1);need(!validate_task_personal_cancellation_results(f.common,&f.state).ok,"result serial cannot borrow any actual fact");f.state=original;auto changed=f.state;changed.cancellations.find(id)->sender_declaration.template_id="changed";need(!task_personal_cancellation_new_result_source(original,changed,"carrier","wait",ReceiptDetails{AdvanceDetails{},{}},0).ok,"old business fields remain immutable");changed=original;changed.cancellations.find(id)->actual_result->request_sequence=2;need(!task_personal_cancellation_new_result_source(original,changed,"carrier","wait",ReceiptDetails{AdvanceDetails{},{}},0).ok,"old permanent binding remains immutable");
 const auto previous=f.state;auto second=f.cancel();auto next=f.commit(second,2);need(!task_personal_cancellation_new_result_source(previous,f.state,"other",next->kind,*next->details,0).ok,"another actor cannot borrow cancellation");auto bad=*next->details;std::get<InteractionEffect>(bad.data).settlement_result=id;need(!task_personal_cancellation_new_result_source(previous,f.state,"carrier",next->kind,bad,0).ok,"new request cannot point at older source");bad=*next->details;std::get<InteractionEffect>(bad.data).party_id="party";need(!task_personal_cancellation_new_result_source(previous,f.state,"carrier",next->kind,bad,0).ok,"unrelated mixed receipt rejected");need(bind_task_personal_cancellation_result(f.common,f.state,second,"carrier",2,*next).ok,"second genuine request binds its own fact");need(validate_task_personal_cancellation_results(f.common,&f.state).ok,"two requests retain actual ordered identities");need(!validate_task_personal_cancellation_results(f.common,nullptr).ok,"selected command cannot lose its independent state");
 auto actual=f.state;f.state.cancellations.find(second)->tick=1;need(!validate_task_personal_cancellation_results(f.common,&f.state).ok,"zero-time cancellation cannot borrow future phase");f.state=actual;f.common.state().results={};f.common.state().history.clear();need(validate_task_personal_cancellation_results(f.common,&f.state).ok,"both original receipts survive full prune");f.state.cancellations.find(second)->actual_result=f.state.cancellations.find(id)->actual_result;need(!validate_task_personal_cancellation_results(f.common,&f.state).ok,"pruning cannot relink older actual request");std::cout<<checks<<" cancellation actual-result boundaries; original Task business separate\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
